export type Flatten<T> = { [K in keyof T]: T[K] } & {};
export interface Schema<O> { _o: O; extend<E extends object>(e: E): Schema<Flatten<O & { [K in keyof E]: E[K] extends Schema<infer X> ? X : never }>> }
export declare function lit<const L extends string>(l: L): Schema<L>;
export declare function obj<S extends object>(s: S): Schema<{ [K in keyof S]: S[K] extends Schema<infer X> ? X : never }>;
export declare function union<A extends Schema<any>[]>(a: A): Schema<A[number]['_o']>;
export declare const num: Schema<number>;
export type infer<S> = S extends Schema<infer O> ? O : never;
